<script>
import permissions from "../common/permissions.js";
import VirtualExpoGoldCarousel from "../components/VirtualExpoGoldCarousel";
import OnboardingChecklist from "../components/OnboardingChecklist.vue";
import api from "../common/api";
import ContractorDashboard from "../components/ContractorDashboard.vue";

export default {
    components: {ContractorDashboard, OnboardingChecklist, VirtualExpoGoldCarousel},
    props: ["forbidden"],
    data() {
        return {
            onboardingAttrs: {
                persistent: true,
            },
            onboardingData: {},
            items: [
                {
                    icon: 'mdi-help-circle',
                    title: 'Enquiries',
                    route_name: "questions",
                    display: true,
                },
                {
                    icon: 'mdi-folder-open',
                    title: 'Archived Enquiries',
                    route_name: "archived-enquiries",
                    display: true,
                },
                {
                    icon: 'mdi-account-group',
                    title: 'Our Partners',
                    display: true,
                    route_name: "our-partners",
                },
                {
                    icon: 'mdi-phone',
                    title: 'Customer Support',
                    route_name: "customer-support",
                    display: true,
                },
                {
                    icon: 'mdi-finance',
                    title: 'Reporting',
                    route_name: "reports",
                    display: true,
                },
                {
                    icon: 'mdi-cogs',
                    title: 'Account Settings',
                    display: true,
                    route_name: "profile",
                },
            ]
        }
    },

    computed: {
        onboardingActive() {
            return this.$store.getters.getSession.user.onboarding_active ?? false;
        },
        showOnboardingDialog: {
            get() {
                return this.onboardingActive;
            },
            set(val) {
                return val;
            }
        },
    },

    methods: {
        allowQuestions() {
            return permissions.can(permissions.view_enquiries_ph);
        },
        allowVirtualExpo() {
            return true;
        },
        getLogo() {
            return window.wsSettings.logo_image;
        },

        isAuthorized: function () {
            return permissions.isAuthorized()
        },

        isContractor() {
            return permissions.hasRole(permissions.role_contractor);
        },

        load() {
            const self = this;

            let userId = self.$store.getters.getSession.user.id;

            if (userId) {
                api.getOnboardingChecklist(userId).then(response => {
                    self.onboardingData = response.data;
                    self.onboardingData.id = self.onboardingData.user_id;
                    self.onboardingAttrs.persistent = !self.onboardingData.account_setup;

                    delete self.onboardingData.user_id;
                });
            }
        }
    },

    mounted() {
        const self = this;

        self.load();
    },
};
</script>

